static constexpr uint8_t SCOOTER_HEARTBEAT[] = {
  0x5A, 0xA5, 0x01, 0x3D, 0x20, 0x55, 0x7C, 0x7C, 0x54, 0xFE
};
static constexpr uint8_t SCOOTER_LOCK[] = {
