AltFwDecoder otaEnvelope;

int hexNibble(char c)
{
  if(c >= '0' && c <= '9') return c - '0';
  if(c >= 'a' && c <= 'f') return c - 'a' + 10;
  if(c >= 'A' && c <= 'F') return c - 'A' + 10;
  return -1;
}

bool secureEqual(const uint8_t* a, const uint8_t* b, size_t length)
{
  uint8_t diff = 0;
  for(size_t i = 0; i < length; i++) diff |= a[i] ^ b[i];
  return diff == 0;
}

bool getJsonString(const String& json, const char* key, String& value)
{
  String marker = String("\"") + key + "\":\"";
  int start = json.indexOf(marker);
  if(start < 0) return false;
  start += marker.length();
  int end = json.indexOf('"', start);
  if(end < 0) return false;
  value = json.substring(start, end);
  return true;
}

size_t getJsonSize(const String& json, const char* key)
{
  String marker = String("\"") + key + "\":";
  int start = json.indexOf(marker);
  if(start < 0) return 0;
  start += marker.length();
  size_t value = 0;
  while(start < json.length() && json[start] >= '0' && json[start] <= '9')
  {
    value = value * 10 + (json[start] - '0');
    start++;
  }
  return value;
}

bool parseHexExact(const String& hex, uint8_t* output, size_t length)
{
  if(hex.length() != length * 2) return false;
  for(size_t i = 0; i < length; i++)
  {
    int hi = hexNibble(hex[i * 2]);
    int lo = hexNibble(hex[i * 2 + 1]);
    if(hi < 0 || lo < 0) return false;
    output[i] = (uint8_t)((hi << 4) | lo);
  }
  return true;
}

bool verifyFirmwareManifest(const String& version, const String& model, size_t size,
                            const String& shaHex, const String& signatureBase64)
{
  if(model != "S90L" || signatureBase64.length() == 0) return false;
  String canonical = "USNSC1|iot|" + version + "|" + model + "|" + String(size) + "|" + shaHex + "|";
#if CONFIG_IDF_TARGET_ESP32S3
  canonical += "|access2|esp32s3";
#else
  canonical += "|access2|esp32";
#endif
  uint8_t digest[32];
  mbedtls_sha256_context sha;
  mbedtls_sha256_init(&sha);
  mbedtls_sha256_starts(&sha, 0);
  mbedtls_sha256_update(&sha, (const uint8_t*)canonical.c_str(), canonical.length());
  mbedtls_sha256_finish(&sha, digest);
  mbedtls_sha256_free(&sha);
  uint8_t signature[96];
  size_t signatureLength = 0;
  if(mbedtls_base64_decode(signature, sizeof(signature), &signatureLength,
                           (const uint8_t*)signatureBase64.c_str(), signatureBase64.length()) != 0)
    return false;
  mbedtls_pk_context key;
  mbedtls_pk_init(&key);
  int result = mbedtls_pk_parse_public_key(
    &key, (const uint8_t*)USNSC_RELEASE_PUBLIC_KEY, strlen(USNSC_RELEASE_PUBLIC_KEY) + 1);
  if(result == 0)
    result = mbedtls_pk_verify(&key, MBEDTLS_MD_SHA256, digest, sizeof(digest), signature, signatureLength);
  mbedtls_pk_free(&key);
  return result == 0;
}

String bytesToHex(const uint8_t* data, size_t length)
{
  static const char* digits = "0123456789ABCDEF";
  String result;
  result.reserve(length * 2);
  for(size_t i = 0; i < length; i++)
  {
    result += digits[data[i] >> 4];
    result += digits[data[i] & 0x0F];
  }
  return result;
}

void hmacSha256Key(const uint8_t* key, size_t keyLength,
                   const uint8_t* data, size_t dataLength, uint8_t output[32])
{
  const mbedtls_md_info_t* info = mbedtls_md_info_from_type(MBEDTLS_MD_SHA256);
  mbedtls_md_hmac(info, key, keyLength, data, dataLength, output);
}


void writeCounterBE(uint32_t counter, uint8_t output[4])
{
  output[0] = (counter >> 24) & 0xFF;
  output[1] = (counter >> 16) & 0xFF;
  output[2] = (counter >> 8) & 0xFF;
  output[3] = counter & 0xFF;
}


void notifyJson(const String& json)
{
  if(!bleConnected || !rxChar) return;
  notifyPhone(json.c_str());
}


void notifyOtaStatus(const char* stage, const char* error=nullptr)
{
  String response = "{\"type\":\"esp_ota_status\",\"stage\":\"";
  response += stage;
  response += "\",\"received\":" + String(otaReceived);
  response += ",\"size\":" + String(otaExpectedEnvelopeSize);
  response += ",\"version\":\"" + (otaTargetVersion.length() ? otaTargetVersion : String(IOT_FIRMWARE_VERSION)) + "\"";
  if(error)
  {
    response += ",\"error\":\"";
    response += error;
    response += "\"";
  }
  response += "}";
  notifyJson(response);
}

void abortOta(const char* error, bool notify=true)
{
  Serial.printf("OTA aborted: %s (flash: %s)\n", error ? error : "aborted", Update.errorString());
  if(otaActive) Update.abort();
  otaEnvelope.abort();
  otaActive = false;
  otaError = error ? error : "aborted";
  if(notify) notifyOtaStatus("error", otaError.c_str());
}

String firmwareDeviceId()
{
  static String cached;
  if(cached.length() == 12) return cached;

  char hardwareId[13];
  snprintf(hardwareId, sizeof(hardwareId), "%012llX",
           (unsigned long long)(ESP.getEfuseMac() & 0xFFFFFFFFFFFFULL));

  Preferences identityPrefs;
  if(identityPrefs.begin("alttech-id", false))
  {
    String stored = identityPrefs.getString("device_id", "");
    stored.toUpperCase();
    bool valid = stored.length() == 12;
    for(size_t i = 0; valid && i < stored.length(); i++)
      valid = isxdigit((unsigned char)stored[i]);
    cached = valid ? stored : String(hardwareId);
    if(!valid) identityPrefs.putString("device_id", cached);
    identityPrefs.end();
  }
  else cached = String(hardwareId);

  return cached;
}


bool writeOtaPlain(const uint8_t* data, size_t length, void*)
{
  return Update.write(const_cast<uint8_t*>(data), length) == length;
}

void beginOta(size_t size, size_t envelopeSize, const String& shaHex, const String& version,
              const String& model, const String& signature, size_t ackEvery)
{
  Serial.printf("OTA begin: image=%u envelope=%u heap=%u stack=%u\n", unsigned(size), unsigned(envelopeSize), unsigned(ESP.getFreeHeap()), unsigned(uxTaskGetStackHighWaterMark(nullptr)));
  if(otaActive) abortOta("restarted", false);
  otaExpectedSize = size;
  otaExpectedEnvelopeSize = envelopeSize;
  otaReceived = 0;
  otaExpectedSequence = 0;
  otaAckEvery = (uint8_t)constrain(ackEvery ? ackEvery : 1, 1, 32);
  otaTargetVersion = version;
  otaError = "";
  otaRebootAt = 0;
  if(!size || envelopeSize != size + AltFwDecoder::Overhead || !parseHexExact(shaHex, otaExpectedSha, sizeof(otaExpectedSha)) ||
     !verifyFirmwareManifest(version, model, size, shaHex, signature))
  {
    abortOta("invalid_manifest");
    return;
  }
  if(!Update.begin(size, U_FLASH))
  {
    abortOta("no_ota_partition");
    return;
  }
  if(!otaEnvelope.begin(envelopeSize, size, shaHex, firmwareDeviceId(), writeOtaPlain, nullptr))
  {
    abortOta(otaEnvelope.error());
    return;
  }
  otaActive = true;
  Serial.println("OTA ready to receive");
  notifyOtaStatus("receiving");
}

void notifyChunk(uint16_t sequence, bool ok, const char* error=nullptr)
{
  String response = "{\"type\":\"esp_ota_chunk_ack\",\"seq\":" + String(sequence);
  response += ",\"ok\":";
  response += ok ? "true" : "false";
  response += ",\"received\":" + String(otaReceived);
  response += ",\"nextSeq\":" + String(otaExpectedSequence);
  if(error) response += String(",\"error\":\"") + error + "\"";
  response += "}";
  notifyJson(response);
}

void handleOtaChunk(const uint8_t* data, size_t length)
{
  if(!bleAuthorized || !otaActive || length < 18) return;
  uint16_t sequence = data[2] | ((uint16_t)data[3] << 8);
  uint8_t payloadLength = data[4];
  if(!payloadLength || payloadLength > 128 || length != (size_t)payloadLength + 17)
  {
    notifyChunk(sequence, false, "invalid_chunk");
    return;
  }
  if(sequence < otaExpectedSequence)
  {
    notifyChunk(sequence, true);
    return;
  }
  if(sequence != otaExpectedSequence || otaReceived + payloadLength > otaExpectedEnvelopeSize)
  {
    notifyChunk(sequence, false, "sequence");
    return;
  }

  uint8_t counterData[4];
  writeCounterBE((uint32_t)sequence + 1, counterData);
  uint8_t macMessage[135];
  memcpy(macMessage, "OTM", 3);
  memcpy(macMessage + 3, counterData, 4);
  memcpy(macMessage + 7, data + 5, payloadLength);
  uint8_t expectedMac[32];
  hmacSha256Key(sessionKey, sizeof(sessionKey), macMessage, payloadLength + 7, expectedMac);
  if(!secureEqual(expectedMac, data + 5 + payloadLength, 12))
  {
    notifyChunk(sequence, false, "mac");
    return;
  }

  uint8_t plain[128];
  for(size_t offset = 0, block = 0; offset < payloadLength; offset += 32, block++)
  {
    uint8_t blockData[4];
    writeCounterBE(block, blockData);
    uint8_t streamMessage[11];
    memcpy(streamMessage, "OTA", 3);
    memcpy(streamMessage + 3, counterData, 4);
    memcpy(streamMessage + 7, blockData, 4);
    uint8_t stream[32];
    hmacSha256Key(sessionKey, sizeof(sessionKey), streamMessage, sizeof(streamMessage), stream);
    for(size_t i = 0; i < 32 && offset + i < payloadLength; i++)
      plain[offset + i] = data[5 + offset + i] ^ stream[i];
  }

  if(!otaEnvelope.feed(plain, payloadLength))
  {
    abortOta(otaEnvelope.error());
    return;
  }
  otaReceived = otaEnvelope.received();
  otaExpectedSequence++;
  if(otaAckEvery <= 1 || otaExpectedSequence % otaAckEvery == 0 ||
     otaReceived == otaExpectedEnvelopeSize)
    notifyChunk(sequence, true);
}

void finishOta()
{
  if(!otaActive || otaReceived != otaExpectedEnvelopeSize)
  {
    abortOta("incomplete_image");
    return;
  }
  notifyOtaStatus("verifying");
  if(!otaEnvelope.finish())
  {
    abortOta(otaEnvelope.error());
    return;
  }
  if(!Update.end(true))
  {
    abortOta("image_rejected");
    return;
  }
  otaActive = false;
  otaRebootAt = millis() + 1200;
  notifyOtaStatus("rebooting");
}

class ServerCallbacks : public BLEServerCallbacks
{
 public:
  void onConnect(BLEServer*) override
  { bleWorker.post(AltBleWorker::Connected); }
  static void connected()
  {
    Serial.println("BLE connected");
    bleConnected = true;
    bleConnectedSince = millis();
  }

  void onDisconnect(BLEServer*) override
  { bleWorker.post(AltBleWorker::Disconnected); }
  static void disconnected()
  {
    Serial.println("BLE disconnected");
    if(otaActive) abortOta("ble_disconnected", false);
    bleConnected = false;
    bleAuthorized = false;
    accessEndpoint.reset();
    serverPtr->startAdvertising();
  }
};

class TxCallbacks : public BLECharacteristicCallbacks
{
 public:
  void onWrite(BLECharacteristic* characteristic) override
  { bleWorker.post(AltBleWorker::Write, characteristic->getData(), characteristic->getLength()); }
  static void handle(uint8_t* data, size_t length)
  {
    if(!length || length > 512) return;
    if(length >= 2 && data[0] == OTA_MAGIC_0 && data[1] == OTA_MAGIC_1)
    {
      if(!accessEndpoint.allowBinary(data[1])) return;
      handleOtaChunk(data, length);
      return;
    }

    String json;
    bool accessFramed = length >= 2 && data[0] == 0xa7 && data[1] == 0x62;
    if(accessFramed) {
      if(accessEndpoint.unwrap(data, length, json) != 1) return;
    } else
    {
    json.reserve(length + 1);
    for(size_t i = 0; i < length; i++) json += (char)data[i];
    }

  if(json.indexOf("\"cmd\":\"enrollment_") >= 0)
  {
    String command, requestId, nonce, part, reply;
    getJsonString(json, "cmd", command);
    getJsonString(json, "requestId", requestId);
    getJsonString(json, "nonce", nonce);
    getJsonString(json, "part", part);
    if(command == "enrollment_info") reply = enrollmentRuntime.info(firmwareDeviceId(), part, IOT_FIRMWARE_VERSION);
    else if(command == "enrollment_proof") reply = enrollmentRuntime.start(requestId, nonce, firmwareDeviceId());
    else if(command == "enrollment_read") reply = enrollmentRuntime.read(requestId, part);
    else return;
    notifyJson(reply);
    return;
  }
    String accessCommand;
    getJsonString(json, "cmd", accessCommand);
    if(!accessFramed && accessCommand == "access") {
      String id, op, section, bytes;
      getJsonString(json, "id", id); getJsonString(json, "op", op);
      getJsonString(json, "section", section); getJsonString(json, "data", bytes);
      static uint32_t accessCounter = 0;
      accessEndpoint.handshake(id, op, section, (int)getJsonSize(json, "part"), bytes,
        rxChar, bleAuthorized, sessionKey, accessCounter);
      return;
    }
    String accessImageHash;
    getJsonString(json, "sha256", accessImageHash);
    if(!accessFramed || !accessEndpoint.allow(accessCommand, nullptr, false, false, accessImageHash)) return;
    if(!bleAuthorized) return;

    if(json.indexOf("\"cmd\":\"device_info\"") >= 0)
    {
      String info = "{\"type\":\"device_info\",\"modelId\":\"S90L\",\"model\":\"Ninebot Max S90L\",\"generation\":\"SNSC 2.4\",\"tags\":" + configuredScooterTags + ",\"iotVersion\":\"0.0.0\",\"deviceId\":\"";
      info += firmwareDeviceId();
      info += "\",\"capabilities\":[\"signed_config\",\"esp_ota\"]}";
      notifyJson(info);
      return;
    }
    if(json.indexOf("\"cmd\":\"device_config_signed\"") >= 0)
  {
    String token;
    int result = getJsonString(json, "token", token) ? accessEndpoint.configure(token) : -1;
    String reply = "{\"type\":\"device_config_ack\",\"ok\":";
    reply += result >= 0 ? "true" : "false";
    reply += ",\"rebootRequired\":";
    reply += result == 1 ? "true}" : "false}";
    notifyPhone(reply.c_str());
    return;
  }

  if(json.indexOf("\"cmd\":\"firmware_info\"") >= 0)
    {
      notifyJson("{\"type\":\"firmware_info\",\"iotVersion\":\"0.0.0\",\"controllerVersion\":null}");
      return;
    }
    if(json.indexOf("\"cmd\":\"esp_ota_begin\"") >= 0)
    {
      String shaHex;
      String version;
      String model;
      String signature;
      if(getJsonString(json, "sha256", shaHex) && getJsonString(json, "version", version) &&
         getJsonString(json, "model", model) && getJsonString(json, "signature", signature))
      {
        for(uint8_t i = 0; i < 3; i++)
        {
          scooterUart.write(SCOOTER_LOCK, sizeof(SCOOTER_LOCK));
          delay(20);
        }
        delay(120);
        beginOta(getJsonSize(json, "size"), getJsonSize(json, "envelopeSize"), shaHex, version, model, signature,
                 getJsonSize(json, "ackEvery"));
      }
      else
        abortOta("invalid_manifest");
      return;
    }
    if(json.indexOf("\"cmd\":\"esp_ota_end\"") >= 0)
    {
      finishOta();
      return;
    }
    if(json.indexOf("\"cmd\":\"esp_ota_abort\"") >= 0)
    {
      abortOta("cancelled");
      return;
    }
    if(json.indexOf("\"cmd\":\"esp_ota_status\"") >= 0)
    {
      if(otaError.length()) notifyOtaStatus("error", otaError.c_str());
      else if(otaRebootAt) notifyOtaStatus("rebooting");
      else if(otaActive) notifyOtaStatus("receiving");
      else notifyOtaStatus("idle");
    }
  }
};

void processBleEvent(AltBleWorker::Kind kind, uint8_t* data, size_t length)
{
  if(kind == AltBleWorker::Connected) ServerCallbacks::connected();
  else if(kind == AltBleWorker::Disconnected) ServerCallbacks::disconnected();
  else if(kind == AltBleWorker::Write) { if(bleConnected) TxCallbacks::handle(data, length); }
  else {
    Serial.println("BLE queue overflow; closing session");
    ServerCallbacks::disconnected();
    if(serverPtr) serverPtr->disconnect(serverPtr->getConnId());
  }
}

void setup()
{
  Serial.begin(115200);
  if(!bleWorker.begin(processBleEvent)) { Serial.println("BLE worker allocation failed"); while(true) delay(1000); }
  firmwareDeviceId();
  configPrefs.begin("nb-iot", false);
if(configPrefs.isKey("pair_secret")) configPrefs.remove("pair_secret");
configuredDeviceName = String("ALT-") + firmwareDeviceId();
  configuredScooterTags = configPrefs.getString("fw_tags", "[]");
  configuredUartRx = configPrefs.getUChar("uart_rx", UART_RX);
  configuredUartTx = configPrefs.getUChar("uart_tx", UART_TX);
  configuredUartRxBoard = configPrefs.getBool("uart_rx_board", false);
  configuredUartTxBoard = configPrefs.getBool("uart_tx_board", false);
  if(configPrefs.getString("ble_name", "") != configuredDeviceName) configPrefs.putString("ble_name", configuredDeviceName);
  if(!configPrefs.isKey("uart_rx")) configPrefs.putUChar("uart_rx", configuredUartRx);
  if(!configPrefs.isKey("uart_tx")) configPrefs.putUChar("uart_tx", configuredUartTx);
  if(!configPrefs.isKey("uart_rx_board")) configPrefs.putBool("uart_rx_board", configuredUartRxBoard);
  if(!configPrefs.isKey("uart_tx_board")) configPrefs.putBool("uart_tx_board", configuredUartTxBoard);
  configPrefs.end();
configuredScooterTags = AltConfig::hardwareTags(configuredScooterTags);
AltConfig::load(configuredDeviceName, configuredScooterTags, configuredUartRx, configuredUartTx,
  configuredUartRxBoard, configuredUartTxBoard, configuredLegacyProtectedController);
configuredDeviceName = String("ALT-") + firmwareDeviceId();
  scooterUart.begin(UART_BAUD, SERIAL_8N1,
                    configuredUartRxBoard ? RX : configuredUartRx,
                    configuredUartTxBoard ? TX : configuredUartTx);
  BLEDevice::init(configuredDeviceName.c_str());
if(!enrollmentRuntime.begin()) Serial.println("Enrollment identity unavailable");
if(!accessEndpoint.begin()) Serial.println("Access identity unavailable");
  BLEDevice::setMTU(185);
  String serviceUuid = AltBleUuid::decode(AltBleUuid::SERVICE);
  String txUuid = AltBleUuid::decode(AltBleUuid::TX);
  String rxUuid = AltBleUuid::decode(AltBleUuid::RX);
  serverPtr = BLEDevice::createServer();
  serverPtr->setCallbacks(new ServerCallbacks());
  BLEService* service = serverPtr->createService(serviceUuid.c_str());
  BLECharacteristic* tx = service->createCharacteristic(
    txUuid.c_str(), BLECharacteristic::PROPERTY_WRITE | BLECharacteristic::PROPERTY_WRITE_NR);
  tx->setCallbacks(new TxCallbacks());
  rxChar = service->createCharacteristic(
    rxUuid.c_str(), BLECharacteristic::PROPERTY_NOTIFY | BLECharacteristic::PROPERTY_READ);
  rxChar->addDescriptor(new BLE2902());
  service->start();
  BLEAdvertising* advertising = BLEDevice::getAdvertising();
  advertising->addServiceUUID(serviceUuid.c_str());
  advertising->start();
  Serial.println("USNSC BLE bootstrap 0.0.0 ready");
}

void loop()
{
  uint32_t now = millis();
if(bleConnected && !bleAuthorized && millis() - bleConnectedSince >= 180000) {
  bleConnectedSince = millis();
  if(serverPtr) serverPtr->disconnect(serverPtr->getConnId());
}

  if(otaRebootAt && (int32_t)(now - otaRebootAt) >= 0) ESP.restart();
  if(now - lastHeartbeat >= HEARTBEAT_INTERVAL)
  {
    scooterUart.write(SCOOTER_HEARTBEAT, sizeof(SCOOTER_HEARTBEAT));
    lastHeartbeat = now;
  }
  delay(2);
}

