#pragma once
#include <Arduino.h>
#include <FS.h>
#include <esp_random.h>
#include <esp_bt.h>
#include <mbedtls/gcm.h>
#include <mbedtls/platform_util.h>

// Temporary ESC staging: independent authenticated records, key only in RAM.
class AltEncryptedImageStore {
 public:
  ~AltEncryptedImageStore() { clear(); }
  void clear() {
    mbedtls_platform_zeroize(key_, sizeof(key_));
    mbedtls_platform_zeroize(pending_, sizeof(pending_));
    active_ = false; complete_ = false; size_ = received_ = used_ = blocks_ = 0;
  }
  bool begin(size_t size) {
    clear();
    if (!size || size > 512 * 1024 || esp_bt_controller_get_status() != ESP_BT_CONTROLLER_STATUS_ENABLED) return false;
    esp_fill_random(key_, sizeof(key_)); esp_fill_random(nonce_, 8);
    size_ = size; active_ = true; return true;
  }
  size_t storedSize() const { return ((size_ + 127) / 128) * 144; }
  bool write(File& file, const uint8_t* bytes, size_t length) {
    if (!active_ || complete_ || !file || !bytes || length > size_ - received_) return false;
    while (length) {
      size_t take = min(length, size_t(128 - used_));
      memcpy(pending_ + used_, bytes, take);
      used_ += take; received_ += take; bytes += take; length -= take;
      if (used_ == 128 && !flush(file)) { clear(); return false; }
    }
    return true;
  }
  bool finish(File& file) {
    if (!active_ || complete_ || received_ != size_) return false;
    if (used_ && !flush(file)) { clear(); return false; }
    file.flush();
    if (file.size() != storedSize()) { clear(); return false; }
    complete_ = true;
    return true;
  }
  bool read(File& file, size_t offset, uint8_t* output, size_t length) const {
    if (!active_ || !complete_ || !file || !output || offset > size_ || length > size_ - offset || file.size() != storedSize()) return false;
    while (length) {
      const size_t block = offset / 128, inside = offset % 128;
      uint8_t record[144], plain[128];
      if (!file.seek(block * 144) || file.read(record, sizeof(record)) != sizeof(record)) return false;
      const bool ok = crypt(false, block, record, plain, record + 128);
      if (!ok) { mbedtls_platform_zeroize(plain, sizeof(plain)); return false; }
      const size_t take = min(length, size_t(128 - inside));
      memcpy(output, plain + inside, take); mbedtls_platform_zeroize(plain, sizeof(plain));
      output += take; offset += take; length -= take;
    }
    return true;
  }
 private:
  uint8_t key_[32] = {}, nonce_[8] = {}, pending_[128] = {};
  size_t size_ = 0, received_ = 0, used_ = 0, blocks_ = 0;
  bool active_ = false, complete_ = false;
  bool crypt(bool encrypt, size_t block, const uint8_t* input, uint8_t* output, uint8_t* tag) const {
    uint8_t iv[12], aad[8]; memcpy(iv, nonce_, 8);
    for (size_t i = 0; i < 4; ++i) {
      iv[8 + i] = uint32_t(block) >> (24 - i * 8);
      aad[i] = iv[8 + i]; aad[4 + i] = uint32_t(size_) >> (24 - i * 8);
    }
    mbedtls_gcm_context context; mbedtls_gcm_init(&context);
    int result = mbedtls_gcm_setkey(&context, MBEDTLS_CIPHER_ID_AES, key_, 256);
    if (!result) result = encrypt ? mbedtls_gcm_crypt_and_tag(&context, MBEDTLS_GCM_ENCRYPT,
      128, iv, sizeof(iv), aad, sizeof(aad), input, output, 16, tag) :
      mbedtls_gcm_auth_decrypt(&context, 128, iv, sizeof(iv), aad, sizeof(aad), tag, 16, input, output);
    mbedtls_gcm_free(&context); return result == 0;
  }
  bool flush(File& file) {
    uint8_t record[144];
    memset(pending_ + used_, 0, sizeof(pending_) - used_);
    const bool ok = crypt(true, blocks_, pending_, record, record + 128) && file.write(record, sizeof(record)) == sizeof(record);
    mbedtls_platform_zeroize(pending_, sizeof(pending_)); used_ = 0;
    if (ok) blocks_++;
    return ok;
  }
};

#pragma once
#include "device_identity_runtime.h"
#include <freertos/FreeRTOS.h>
#include <freertos/queue.h>
#include <freertos/semphr.h>
#include <freertos/task.h>

#ifndef ALTTECH_ENROLLMENT_V2
#define ALTTECH_ENROLLMENT_V2 0
#endif
#ifndef ALTTECH_CONTROLLER_PROOF
#define ALTTECH_CONTROLLER_PROOF 0
#endif

class AltEnrollmentRuntime {
 public:
  bool begin() {
    if (!identity_.begin()) return false;
    mutex_ = xSemaphoreCreateMutex();
    queue_ = xQueueCreate(1, sizeof(Job));
    if (!mutex_ || !queue_) return false;
    return xTaskCreate(worker, "alt-enroll", 8192, this, 1, &task_) == pdPASS;
  }

  String info(const String& deviceId, const String& part, const String& version = "") const {
    int index = partIndex(part, 2);
    if (!task_ || index < 0) return error("identity_unavailable");
    String key = identity_.publicKey();
    return String("{\"type\":\"enrollment_info\",\"deviceId\":\"") + deviceId +
      "\",\"part\":\"" + part + "\",\"data\":\"" + key.substring(index * 64, (index + 1) * 64) +
      "\",\"v\":\"" + version + "\",\"cp\":" + (ALTTECH_CONTROLLER_PROOF ? "true" : "false") + "}";
  }

  String start(const String& requestId, const String& nonce, const String& deviceId,
      const String& serial = "", const String& protocol = "") {
    if (!task_ || !validRequest(requestId) || !validHex(nonce, 64) || !validHex(deviceId, 12))
      return error("invalid_enrollment");
    if (xSemaphoreTake(mutex_, 0) != pdTRUE) return error("enrollment_busy");
    bool same = requestId == current_.requestId && nonce == current_.nonce &&
      serial == current_.serial && protocol == current_.protocol;
    if (same) {
      xSemaphoreGive(mutex_);
      return pending(requestId);
    }
    if (busy_ || (everStarted_ && millis() - lastStart_ < 2000)) {
      xSemaphoreGive(mutex_);
      return error("enrollment_busy");
    }
    Job next = {};
    requestId.toCharArray(next.requestId, sizeof(next.requestId));
    nonce.toCharArray(next.nonce, sizeof(next.nonce));
    deviceId.toCharArray(next.deviceId, sizeof(next.deviceId));
    serial.toCharArray(next.serial, sizeof(next.serial));
    protocol.toCharArray(next.protocol, sizeof(next.protocol));
    current_ = next;
    signature_[0] = 0;
    failed_ = false;
    busy_ = true;
    lastStart_ = millis();
    everStarted_ = true;
    bool queued = xQueueSend(queue_, &next, 0) == pdTRUE;
    if (!queued) { busy_ = false; failed_ = true; }
    xSemaphoreGive(mutex_);
    return queued ? pending(requestId) : error("enrollment_busy");
  }

  String read(const String& requestId, const String& part) {
    int index = partIndex(part, 1);
    if (!task_ || index < 0 || !validRequest(requestId)) return error("invalid_enrollment");
    if (xSemaphoreTake(mutex_, pdMS_TO_TICKS(10)) != pdTRUE) return pending(requestId);
    String result;
    if (requestId != current_.requestId) result = error("enrollment_not_found");
    else if (busy_) result = pending(requestId);
    else if (failed_) result = error("enrollment_sign_failed");
    else result = String("{\"type\":\"enrollment_piece\",\"requestId\":\"") + requestId +
      "\",\"part\":\"" + part + "\",\"data\":\"" + String(signature_).substring(index * 64, (index + 1) * 64) + "\"}";
    xSemaphoreGive(mutex_);
    return result;
  }

  String controllerInfo(const String& id) {
    if (!task_ || !validRequest(id)) return error("invalid_enrollment");
    if (xSemaphoreTake(mutex_, pdMS_TO_TICKS(10)) != pdTRUE) return pending(id);
    String result = pending(id);
    if (id == current_.requestId && !busy_ && !failed_ && current_.serial[0]) {
      result = String("{\"type\":\"controller_attestation\",\"requestId\":\"") + id +
        "\",\"serial\":\"" + current_.serial + "\",\"protocol\":\"" + current_.protocol + "\"}";
    }
    xSemaphoreGive(mutex_); return result;
  }
  static bool validChallenge(const String& id, const String& nonce) {
    return validRequest(id) && validHex(nonce, 64);
  }
 private:
  struct Job { char requestId[37]; char nonce[65]; char deviceId[13]; char serial[21]; char protocol[10]; };
  AltDeviceIdentity identity_;
  SemaphoreHandle_t mutex_ = nullptr;
  QueueHandle_t queue_ = nullptr;
  TaskHandle_t task_ = nullptr;
  Job current_ = {};
  char signature_[129] = {};
  bool busy_ = false, failed_ = false, everStarted_ = false;
  uint32_t lastStart_ = 0;

  static bool validHex(const String& value, size_t length) {
    if (value.length() != length) return false;
    for (char c : value) if (!isHexadecimalDigit(c)) return false;
    return true;
  }
  static bool validRequest(const String& id) {
    if (id.length() != 36) return false;
    for (size_t i = 0; i < 36; i++) {
      bool dash = i == 8 || i == 13 || i == 18 || i == 23;
      if (dash ? id[i] != '-' : !isHexadecimalDigit(id[i])) return false;
    }
    return true;
  }
  static int partIndex(const String& part, int maximum) {
    return part.length() == 1 && part[0] >= '0' && part[0] <= '0' + maximum ? part[0] - '0' : -1;
  }
  static String error(const char* reason) {
    return String("{\"type\":\"enrollment_error\",\"error\":\"") + reason + "\"}";
  }
  static String pending(const String& id) {
    return String("{\"type\":\"enrollment_pending\",\"requestId\":\"") + id + "\"}";
  }
  static void worker(void* context) {
    auto* self = static_cast<AltEnrollmentRuntime*>(context);
    Job job;
    for (;;) {
      if (xQueueReceive(self->queue_, &job, portMAX_DELAY) != pdTRUE) continue;
      String signature;
      bool ok = job.serial[0] ? self->identity_.controllerProof(job.requestId, job.nonce, job.serial, job.protocol, signature) :
        self->identity_.enrollmentProof(job.requestId, job.nonce, job.deviceId, signature);
      xSemaphoreTake(self->mutex_, portMAX_DELAY);
      self->failed_ = !ok;
      self->busy_ = false;
      if (ok) signature.toCharArray(self->signature_, sizeof(self->signature_));
      xSemaphoreGive(self->mutex_);
    }
  }
};

#pragma once
#include <Arduino.h>
#include <Preferences.h>
#include <esp_random.h>
#include <esp_bt.h>
#include <mbedtls/ecp.h>
#include <mbedtls/ecdsa.h>
#include <mbedtls/ecdh.h>
#include <mbedtls/hkdf.h>
#include <mbedtls/sha256.h>
#include <mbedtls/platform_util.h>

// Call begin only after BLE starts, so the hardware RNG has an RF entropy source.
// This namespace is shared by bootstrap, protected, and universal OTA images.
class AltDeviceIdentity {
 public:
  AltDeviceIdentity() { mbedtls_ecp_keypair_init(&key_); }
  ~AltDeviceIdentity() { mbedtls_ecp_keypair_free(&key_); }
  AltDeviceIdentity(const AltDeviceIdentity&) = delete;
  AltDeviceIdentity& operator=(const AltDeviceIdentity&) = delete;

  bool begin() {
    if (attempted_) return ready_;
    attempted_ = true;
    Preferences prefs;
    if (!prefs.begin("alt-identity-v2", false)) return false;
    uint8_t blob[98] = {};
    bool existing = prefs.isKey("p256");
    bool ok = true;
    if (existing) {
      ok = prefs.getBytesLength("p256") == sizeof(blob) &&
           prefs.getBytes("p256", blob, sizeof(blob)) == sizeof(blob) && blob[0] == 1;
      if (ok) ok = mbedtls_ecp_read_key(MBEDTLS_ECP_DP_SECP256R1, &key_, blob + 1, 32) == 0;
      if (ok) ok = mbedtls_ecp_mul(&key_.MBEDTLS_PRIVATE(grp), &key_.MBEDTLS_PRIVATE(Q),
          &key_.MBEDTLS_PRIVATE(d), &key_.MBEDTLS_PRIVATE(grp).G, rng, nullptr) == 0;
    } else {
      ok = mbedtls_ecp_gen_key(MBEDTLS_ECP_DP_SECP256R1, &key_, rng, nullptr) == 0;
      blob[0] = 1;
      if (ok) ok = mbedtls_mpi_write_binary(&key_.MBEDTLS_PRIVATE(d), blob + 1, 32) == 0;
    }
    size_t length = 0;
    uint8_t publicBytes[65] = {};
    if (ok) ok = mbedtls_ecp_point_write_binary(&key_.MBEDTLS_PRIVATE(grp),
        &key_.MBEDTLS_PRIVATE(Q), MBEDTLS_ECP_PF_UNCOMPRESSED, &length,
        publicBytes, sizeof(publicBytes)) == 0 && length == sizeof(publicBytes);
    if (ok && existing) ok = memcmp(publicBytes, blob + 33, 65) == 0;
    if (ok && !existing) {
      memcpy(blob + 33, publicBytes, 65);
      ok = prefs.putBytes("p256", blob, sizeof(blob)) == sizeof(blob);
    }
    prefs.end();
    if (ok) publicHex_ = hex(publicBytes, sizeof(publicBytes));
    mbedtls_platform_zeroize(blob, sizeof(blob));
    ready_ = ok;
    return ok;
  }

  bool ready() const { return ready_; }
  String publicKey() const { return ready_ ? publicHex_ : String(); }

  bool firmwareWrapKey(const uint8_t outer[105], uint8_t output[32]) {
    static const char magic[] = "ALTFW04";
    static const char info[] = "ALTFW-DEVICE-V4";
    if (!ready_ || !outer || !output || memcmp(outer, magic, sizeof(magic))) return false;
    uint8_t publicBytes[65], ownHash[32], salt[32], shared[32];
    size_t length = 0;
    mbedtls_ecp_point peer; mbedtls_ecp_point_init(&peer);
    mbedtls_mpi secret; mbedtls_mpi_init(&secret);
    bool ok = mbedtls_ecp_point_write_binary(&key_.MBEDTLS_PRIVATE(grp), &key_.MBEDTLS_PRIVATE(Q),
      MBEDTLS_ECP_PF_UNCOMPRESSED, &length, publicBytes, sizeof(publicBytes)) == 0 && length == 65 &&
      mbedtls_sha256(publicBytes, 65, ownHash, 0) == 0;
    uint8_t difference = 0;
    if (ok) for (size_t i = 0; i < 32; ++i) difference |= ownHash[i] ^ outer[73 + i];
    ok = ok && difference == 0 && mbedtls_ecp_point_read_binary(&key_.MBEDTLS_PRIVATE(grp), &peer, outer + 8, 65) == 0 &&
      mbedtls_ecp_check_pubkey(&key_.MBEDTLS_PRIVATE(grp), &peer) == 0 &&
      mbedtls_ecdh_compute_shared(&key_.MBEDTLS_PRIVATE(grp), &secret, &peer, &key_.MBEDTLS_PRIVATE(d), rng, nullptr) == 0 &&
      mbedtls_mpi_write_binary(&secret, shared, sizeof(shared)) == 0 &&
      mbedtls_sha256(outer, 105, salt, 0) == 0;
    const mbedtls_md_info_t* md = mbedtls_md_info_from_type(MBEDTLS_MD_SHA256);
    if (ok) ok = md && mbedtls_hkdf(md, salt, sizeof(salt), shared, sizeof(shared),
      reinterpret_cast<const uint8_t*>(info), sizeof(info), output, 32) == 0;
    mbedtls_ecp_point_free(&peer); mbedtls_mpi_free(&secret);
    mbedtls_platform_zeroize(shared, sizeof(shared));
    if (!ok) mbedtls_platform_zeroize(output, 32);
    return ok;
  }

  bool signHandshake(const uint8_t* message, size_t length, uint8_t signature[64]) {
    static const char domain[] = "ALTTECH-BLE-V2";
    if (!ready_ || !message || length > 1024 || length < sizeof(domain) || memcmp(message, domain, sizeof(domain))) return false;
    uint8_t digest[32];
    if (mbedtls_sha256(message, length, digest, 0) != 0) return false;
    mbedtls_mpi r, s;
    mbedtls_mpi_init(&r); mbedtls_mpi_init(&s);
    bool ok = mbedtls_ecdsa_sign(&key_.MBEDTLS_PRIVATE(grp), &r, &s, &key_.MBEDTLS_PRIVATE(d),
      digest, sizeof(digest), rng, nullptr) == 0 && mbedtls_mpi_write_binary(&r, signature, 32) == 0 &&
      mbedtls_mpi_write_binary(&s, signature + 32, 32) == 0;
    mbedtls_mpi_free(&r); mbedtls_mpi_free(&s);
    mbedtls_platform_zeroize(digest, sizeof(digest));
    return ok;
  }

  bool enrollmentProof(String requestId, String nonce, String deviceId, String& signature) {
    signature = "";
    if (!ready_ || requestId.length() != 36 || nonce.length() != 64 || deviceId.length() != 12) return false;
    requestId.toLowerCase();
    nonce.toLowerCase();
    deviceId.toUpperCase();
    for (size_t i = 0; i < 36; ++i) {
      bool dash = i == 8 || i == 13 || i == 18 || i == 23;
      if (dash ? requestId[i] != '-' : !isHexadecimalDigit(requestId[i])) return false;
    }
    for (char c : nonce) if (!isHexadecimalDigit(c)) return false;
    for (char c : deviceId) if (!isHexadecimalDigit(c)) return false;
    String message = "ALTTECH-ENROLL-V1\n" + requestId + "\n" + nonce + "\n" +
                     deviceId + "\n" + publicHex_ + "\n";
    uint8_t digest[32];
    if (mbedtls_sha256(reinterpret_cast<const uint8_t*>(message.c_str()), message.length(), digest, 0) != 0) return false;
    mbedtls_mpi r, s;
    mbedtls_mpi_init(&r);
    mbedtls_mpi_init(&s);
    uint8_t bytes[64] = {};
    bool ok = mbedtls_ecdsa_sign(&key_.MBEDTLS_PRIVATE(grp), &r, &s, &key_.MBEDTLS_PRIVATE(d),
        digest, sizeof(digest), rng, nullptr) == 0;
    if (ok) ok = mbedtls_mpi_write_binary(&r, bytes, 32) == 0 &&
                 mbedtls_mpi_write_binary(&s, bytes + 32, 32) == 0;
    if (ok) signature = hex(bytes, sizeof(bytes));
    mbedtls_mpi_free(&r);
    mbedtls_mpi_free(&s);
    mbedtls_platform_zeroize(digest, sizeof(digest));
    return ok;
  }

  bool controllerProof(String requestId, String nonce, const String& serial, const String& protocol, String& signature) {
    signature = "";
    if (!ready_ || requestId.length() != 36 || nonce.length() != 64 || serial.length() < 8 || serial.length() > 20 ||
        (protocol != "protected" && protocol != "standard")) return false;
    for (char c : serial) if (!((c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9'))) return false;
    requestId.toLowerCase(); nonce.toLowerCase();
    String message = "ALTTECH-CONTROLLER-V1\n" + requestId + "\n" + nonce + "\n" + serial + "\n" + protocol + "\n";
    uint8_t digest[32], bytes[64];
    if (mbedtls_sha256(reinterpret_cast<const uint8_t*>(message.c_str()), message.length(), digest, 0)) return false;
    mbedtls_mpi r, s; mbedtls_mpi_init(&r); mbedtls_mpi_init(&s);
    bool ok = mbedtls_ecdsa_sign(&key_.MBEDTLS_PRIVATE(grp), &r, &s, &key_.MBEDTLS_PRIVATE(d), digest, 32, rng, nullptr) == 0 &&
      mbedtls_mpi_write_binary(&r, bytes, 32) == 0 && mbedtls_mpi_write_binary(&s, bytes + 32, 32) == 0;
    if (ok) signature = hex(bytes, sizeof(bytes));
    mbedtls_mpi_free(&r); mbedtls_mpi_free(&s); mbedtls_platform_zeroize(digest, sizeof(digest));
    return ok;
  }

 private:
  mbedtls_ecp_keypair key_;
  bool ready_ = false;
  bool attempted_ = false;
  String publicHex_;
  static int rng(void*, unsigned char* output, size_t length) {
    if (esp_bt_controller_get_status() != ESP_BT_CONTROLLER_STATUS_ENABLED) return MBEDTLS_ERR_ECP_RANDOM_FAILED;
    esp_fill_random(output, length);
    return 0;
  }
  static String hex(const uint8_t* bytes, size_t length) {
    static const char digits[] = "0123456789abcdef";
    String result;
    result.reserve(length * 2);
    for (size_t i = 0; i < length; ++i) {
      result += digits[bytes[i] >> 4];
      result += digits[bytes[i] & 15];
    }
    return result;
  }
};

#pragma once
#include <Preferences.h>
#include <driver/gpio.h>
#include "device_access_verifier.h"
#include "access_build_config.h"

namespace AltConfig {
static constexpr size_t Size = 150;
static const char* const Tags[] = {"has_ext_lock", "has_stem_light", "has_deck_light14",
  "has_deck_light6", "has_front_turn_signals", "has_back_turn_signals"};

inline bool valid(const uint8_t* p) {
  if (memcmp(p, "ATC2", 4) || p[50] > 3 || p[51] < 3 || p[51] > 31 || (p[85] & ~1) || (p[84] & ~63)) return false;
  for (size_t i = p[51]; i < 32; ++i) if (p[52 + i]) return false;
  for (size_t i = 0; i < p[51]; ++i) if (p[52 + i] < 32 || p[52 + i] == '"' || p[52 + i] == '\\') return false;
  int rx = p[50] & 1 ? RX : p[48], tx = p[50] & 2 ? TX : p[49];
  return p[48] <= 48 && p[49] <= 48 && rx != tx && GPIO_IS_VALID_GPIO(rx) && GPIO_IS_VALID_OUTPUT_GPIO(tx);
}
inline bool signature(const uint8_t* p) {
  const char domain[] = "ALTTECH-CONFIG-V2";
  uint8_t data[sizeof(domain) + 86], digest[32];
  memcpy(data, domain, sizeof(domain)); memcpy(data + sizeof(domain), p, 86);
  if (mbedtls_sha256(data, sizeof(data), digest, 0)) return false;
  mbedtls_ecp_group group; mbedtls_ecp_point root; mbedtls_mpi r, s;
  mbedtls_ecp_group_init(&group); mbedtls_ecp_point_init(&root); mbedtls_mpi_init(&r); mbedtls_mpi_init(&s);
  bool ok = mbedtls_ecp_group_load(&group, MBEDTLS_ECP_DP_SECP256R1) == 0 &&
    mbedtls_ecp_point_read_binary(&group, &root, ALTTECH_ACCESS_ROOT, 65) == 0 &&
    mbedtls_ecp_check_pubkey(&group, &root) == 0 && mbedtls_mpi_read_binary(&r, p + 86, 32) == 0 &&
    mbedtls_mpi_read_binary(&s, p + 118, 32) == 0 &&
    mbedtls_ecdsa_verify(&group, digest, sizeof(digest), &root, &r, &s) == 0;
  mbedtls_mpi_free(&r); mbedtls_mpi_free(&s); mbedtls_ecp_point_free(&root); mbedtls_ecp_group_free(&group);
  return ok;
}
inline uint64_t revision(const uint8_t* p) {
  return uint64_t(AltAccess::read32(p + 36)) | uint64_t(AltAccess::read32(p + 40)) << 32;
}
inline String tagJson(uint8_t mask) {
  String out = "[";
  for (size_t i = 0; i < 6; ++i) if (mask & (1 << i)) {
    if (out.length() > 1) out += ',';
    out += '"'; out += Tags[i]; out += '"';
  }
  return out + "]";
}
inline String hardwareTags(const String& old) {
  uint8_t mask = 0;
  for (size_t i = 0; i < 6; ++i) if (old.indexOf(String('"') + Tags[i] + '"') >= 0) mask |= 1 << i;
  return tagJson(mask);
}
inline bool load(String& name, String& tags, uint8_t& rx, uint8_t& tx, bool& rxBoard, bool& txBoard,
    bool& legacyProtectedController) {
  Preferences prefs; uint8_t p[Size];
  if (!prefs.begin("nb-iot", true)) return false;
  bool ok = prefs.getBytesLength("config_v2") == Size && prefs.getBytes("config_v2", p, Size) == Size;
  prefs.end();
  if (!ok || !valid(p) || !signature(p)) return false;
  name = String(reinterpret_cast<const char*>(p + 52), p[51]); tags = tagJson(p[84]);
  rx = p[48]; tx = p[49]; rxBoard = p[50] & 1; txBoard = p[50] & 2;
  legacyProtectedController = p[85] & 1;
  return true;
}
// 0 = unchanged, 1 = saved, -1 = invalid, -2 = storage failure.
inline int save(const String& hex, const uint8_t* deviceHash, uint32_t now, char requestedController[15] = nullptr) {
  if (hex.length() != Size * 2 || !deviceHash || !now) return -1;
  uint8_t p[Size], old[Size];
  for (size_t i = 0; i < Size; ++i) {
    int a = tolower(hex[i * 2]), b = tolower(hex[i * 2 + 1]);
    if (!isHexadecimalDigit(a) || !isHexadecimalDigit(b)) return -1;
    p[i] = ((a <= '9' ? a - '0' : a - 'a' + 10) << 4) | (b <= '9' ? b - '0' : b - 'a' + 10);
  }
  if (!valid(p) || !revision(p) || !AltAccess::same(p + 4, deviceHash, 32) ||
      AltAccess::read32(p + 44) <= now || !signature(p)) return -1;
  if (requestedController) {
    memset(requestedController, 0, 15);
    if (p[51] >= 11 && p[51] <= 17 && !memcmp(p + 52, "SN:", 3)) {
      const size_t length = p[51] - 3;
      if (length >= 8 && length <= 14) memcpy(requestedController, p + 55, length);
    }
  }
  Preferences prefs;
  if (!prefs.begin("nb-iot", false)) return -2;
  bool exists = prefs.getBytesLength("config_v2") == Size && prefs.getBytes("config_v2", old, Size) == Size;
  if (exists && revision(p) <= revision(old)) {
    bool same = revision(p) == revision(old) && !memcmp(p + 48, old + 48, 38);
    prefs.end(); return same ? 0 : -1;
  }
  bool changed = !exists || memcmp(p + 48, old + 48, 38);
  bool ok = prefs.putBytes("config_v2", p, Size) == Size && prefs.getBytes("config_v2", old, Size) == Size && !memcmp(p, old, Size);
  prefs.end(); return ok ? (changed ? 1 : 0) : -2;
}
}

#pragma once
#include "device_access_handshake.h"
#include <freertos/FreeRTOS.h>
#include <freertos/queue.h>
#include <freertos/semphr.h>
#include <freertos/task.h>

#ifndef ALTTECH_ACCESS_V2
#define ALTTECH_ACCESS_V2 0
#endif

class AltAccessRuntime {
 public:
  bool begin(const uint8_t root[65]) {
    if (!root || !identity_.begin()) return false;
    memcpy(root_, root, 65);
    mutex_ = xSemaphoreCreateMutex(); queue_ = xQueueCreate(1, sizeof(uint8_t));
    if (!mutex_ || !queue_) return false;
    return xTaskCreate(worker, "alt-access", 12288, this, 1, &task_) == pdPASS;
  }

  String request(const String& id, const String& op, const String& section, int part, const String& data) {
    if (!validId(id)) return response("", "invalid", "error");
    if (op != "begin" && op != "put" && op != "start" && op != "read" && op != "finish" && op != "ack") return response(id, "invalid", "error");
    if (!task_) return response(id, op, "error");
    if (xSemaphoreTake(mutex_, 0) != pdTRUE) return response(id, op, "wait");
    String result = handle(id, op, section, part, data);
    xSemaphoreGive(mutex_); return result;
  }

  bool takeSession(const String& id, uint8_t key[32], AltAccess::Grant& grant, uint32_t& phoneTime) {
    if (!task_ || xSemaphoreTake(mutex_, 0) != pdTRUE) return false;
    const bool ok = id == id_ && state_ == 4 && millis() - started_ < 90000;
    if (ok) { memcpy(key, key_, 32); grant = grant_; phoneTime = verifiedTime_ + (millis() - verifiedAt_) / 1000; }
    xSemaphoreGive(mutex_); return ok;
  }

  void invalidate() {
    if (!task_ || xSemaphoreTake(mutex_, pdMS_TO_TICKS(10)) != pdTRUE) return;
    cancelled_ = true; id_ = "";
    if (state_ != 2) state_ = 5;
    mbedtls_platform_zeroize(key_, sizeof(key_));
    xSemaphoreGive(mutex_);
  }

 private:
  AltDeviceIdentity identity_;
  AltAccessHandshake handshake_;
  SemaphoreHandle_t mutex_ = nullptr;
  QueueHandle_t queue_ = nullptr;
  TaskHandle_t task_ = nullptr;
  uint8_t root_[65] = {}, token_[306] = {}, hello_[101] = {}, proof_[72] = {};
  uint8_t reply_[161] = {}, ack_[32] = {}, key_[32] = {};
  size_t tokenSize_ = 0, helloSize_ = 0, proofSize_ = 0;
  String id_;
  uint8_t state_ = 0; // 0 idle, 1 upload, 2 worker, 3 hello, 4 complete, 5 failed
  bool cancelled_ = false;
  uint32_t started_ = 0, verifiedTime_ = 0, verifiedAt_ = 0;
  AltAccess::Grant grant_;

  static bool validId(const String& id) {
    if (id.length() != 36) return false;
    for (size_t i = 0; i < 36; ++i) {
      bool dash = i == 8 || i == 13 || i == 18 || i == 23;
      if (dash ? id[i] != '-' : !isHexadecimalDigit(id[i])) return false;
    }
    return true;
  }
  static String response(const String& id, const String& op, const char* status, int part = -1, const uint8_t* bytes = nullptr, size_t size = 0) {
    // op is chosen by the fixed allowlist in handle, never arbitrary BLE text.
    String out = "{\"type\":\"access\",\"id\":\"" + id + "\",\"op\":\"" + op + "\",\"status\":\"" + status + "\"";
    if (part >= 0) out += ",\"part\":" + String(part);
    if (bytes) {
      static const char digits[] = "0123456789abcdef";
      out += ",\"data\":\"";
      for (size_t i = 0; i < size; ++i) { out += digits[bytes[i] >> 4]; out += digits[bytes[i] & 15]; }
      out += "\"";
    }
    return out + "}";
  }
  static bool append(uint8_t* dest, size_t capacity, size_t& used, int part, const String& hex) {
    if (part < 0 || part > 9 || hex.length() < 2 || hex.length() > 64 || hex.length() % 2) return false;
    size_t offset = size_t(part) * 32, size = hex.length() / 2;
    if (offset > used || offset + size > capacity) return false;
    uint8_t bytes[32];
    for (size_t i = 0; i < size; ++i) {
      char a = tolower(hex[i * 2]), b = tolower(hex[i * 2 + 1]);
      if (!isHexadecimalDigit(a) || !isHexadecimalDigit(b)) return false;
      bytes[i] = ((a <= '9' ? a - '0' : a - 'a' + 10) << 4) | (b <= '9' ? b - '0' : b - 'a' + 10);
    }
    if (offset < used) return offset + size <= used && AltAccess::same(dest + offset, bytes, size);
    memcpy(dest + used, bytes, size); used += size; return true;
  }
  String handle(const String& id, const String& op, const String& section, int part, const String& data) {
    if (op != "begin" && op != "put" && op != "start" && op != "read" && op != "finish" && op != "ack") return response(id, "invalid", "error");
    if (state_ == 2) return response(id, op, "wait", part);
    if (op == "begin") {
      if (id_ == id && state_ != 5 && millis() - started_ < 90000) return response(id, op, "ok");
      if (state_ != 0 && state_ != 5 && millis() - started_ < 2000) return response(id, op, "wait");
      id_ = id; cancelled_ = false; tokenSize_ = helloSize_ = proofSize_ = 0;
      mbedtls_platform_zeroize(key_, sizeof(key_)); grant_ = AltAccess::Grant{};
      state_ = 1; started_ = millis(); return response(id, op, "ok");
    }
    if (id_ != id || state_ == 5 || millis() - started_ >= 90000) return response(id, op, "error", part);
    if (op == "put") {
      bool ok = false;
      if (section == "token" && state_ == 1) ok = append(token_, sizeof(token_), tokenSize_, part, data);
      if (section == "hello" && state_ == 1) ok = append(hello_, sizeof(hello_), helloSize_, part, data);
      if (section == "proof" && state_ == 3) ok = append(proof_, sizeof(proof_), proofSize_, part, data);
      if (!ok) state_ = 5;
      String result = response(id, op, ok ? "ok" : "error", part);
      if (section == "token" || section == "hello" || section == "proof") {
        result.remove(result.length() - 1);
        result += ",\"section\":\"" + section + "\"}";
      }
      return result;
    }
    if (op == "start") {
      if (state_ == 3 || state_ == 4) return response(id, op, "ok");
      if (state_ != 1 || tokenSize_ != 306 || helloSize_ != 101) return response(id, op, "error");
      uint8_t job = 1; state_ = 2;
      if (xQueueSend(queue_, &job, 0) != pdTRUE) state_ = 5;
      return response(id, op, state_ == 5 ? "error" : "wait");
    }
    if (op == "read") {
      if ((state_ != 3 && state_ != 4) || part < 0 || part > 5) return response(id, op, "error", part);
      const size_t offset = part * 32;
      return response(id, op, "ok", part, reply_ + offset, part == 5 ? 1 : 32);
    }
    if (op == "finish") {
      if (state_ == 4) return response(id, op, "ok");
      if (state_ != 3 || proofSize_ < 8) return response(id, op, "error");
      uint8_t job = 2; state_ = 2;
      if (xQueueSend(queue_, &job, 0) != pdTRUE) state_ = 5;
      return response(id, op, state_ == 5 ? "error" : "wait");
    }
    if (op == "ack" && state_ == 4) return response(id, op, "ok", -1, ack_, 32);
    return response(id, op, "error");
  }
  static void worker(void* context) {
    auto* self = static_cast<AltAccessRuntime*>(context);
    uint8_t job;
    for (;;) {
      if (xQueueReceive(self->queue_, &job, portMAX_DELAY) != pdTRUE) continue;
      // While state=2, handlers do not mutate the exchange buffers.
      bool ok = job == 1 ? self->handshake_.begin(self->token_, self->hello_, self->root_, self->identity_) && self->handshake_.reply(self->reply_)
        : self->handshake_.finish(self->proof_, self->proofSize_, self->ack_) && self->handshake_.key(self->key_);
      xSemaphoreTake(self->mutex_, portMAX_DELAY);
      if (self->cancelled_) { ok = false; mbedtls_platform_zeroize(self->key_, sizeof(self->key_)); }
      if (job == 2 && ok) { self->grant_ = self->handshake_.grant(); self->verifiedTime_ = self->handshake_.estimatedTime(); self->verifiedAt_ = millis(); }
      self->state_ = ok ? (job == 1 ? 3 : 4) : 5;
      xSemaphoreGive(self->mutex_);
    }
  }
};

#pragma once
#include "device_access_verifier.h"
#include "device_identity_runtime.h"
#include <mbedtls/ecdh.h>
#include <mbedtls/md.h>

class AltAccessHandshake {
 public:
  AltAccessHandshake() { mbedtls_ecp_keypair_init(&ephemeral_); }
  ~AltAccessHandshake() { reset(); mbedtls_ecp_keypair_free(&ephemeral_); }
  AltAccessHandshake(const AltAccessHandshake&) = delete;
  AltAccessHandshake& operator=(const AltAccessHandshake&) = delete;

  void reset() {
    pending_ = false; complete_ = false;
    mbedtls_platform_zeroize(session_, sizeof(session_));
    mbedtls_platform_zeroize(digest_, sizeof(digest_));
    memset(serverHello_, 0, sizeof(serverHello_));
    grant_ = AltAccess::Grant{};
    mbedtls_ecp_keypair_free(&ephemeral_); mbedtls_ecp_keypair_init(&ephemeral_);
  }

  // Run on the crypto worker, not the BLE callback or UART loop.
  bool begin(const uint8_t token[306], const uint8_t hello[101], const uint8_t serverRoot[65], AltDeviceIdentity& identity) {
    reset();
    if (!AltAccess::verify(token, 306, serverRoot, grant_) || !identity.ready()) return false;
    uint8_t own[65], hash[32];
    const String hex = identity.publicKey();
    if (hex.length() != 130) return false;
    for (size_t i = 0; i < 65; ++i) {
      const char a = hex[i * 2], b = hex[i * 2 + 1];
      own[i] = ((a <= '9' ? a - '0' : a - 'a' + 10) << 4) | (b <= '9' ? b - '0' : b - 'a' + 10);
    }
    if (mbedtls_sha256(own, sizeof(own), hash, 0) != 0 || !AltAccess::same(hash, grant_.deviceHash, 32)) return false;
    phoneTime_ = AltAccess::read32(hello + 97);
    if (phoneTime_ < grant_.issued || phoneTime_ >= grant_.expires) return false;
    if (mbedtls_ecp_gen_key(MBEDTLS_ECP_DP_SECP256R1, &ephemeral_, rng, nullptr) != 0) return false;
    size_t written = 0;
    if (mbedtls_ecp_point_write_binary(&ephemeral_.MBEDTLS_PRIVATE(grp), &ephemeral_.MBEDTLS_PRIVATE(Q),
      MBEDTLS_ECP_PF_UNCOMPRESSED, &written, serverHello_, 65) != 0 || written != 65 || rng(nullptr, serverHello_ + 65, 32) != 0) return false;
    static const uint8_t domain[] = "ALTTECH-BLE-V2";
    uint8_t transcript[sizeof(domain) + 306 + 101 + 97];
    size_t pos = 0;
    memcpy(transcript + pos, domain, sizeof(domain)); pos += sizeof(domain);
    memcpy(transcript + pos, token, 306); pos += 306;
    memcpy(transcript + pos, hello, 101); pos += 101;
    memcpy(transcript + pos, serverHello_, 97);
    if (!identity.signHandshake(transcript, sizeof(transcript), serverHello_ + 97) ||
      mbedtls_sha256(transcript, sizeof(transcript), digest_, 0) != 0) return false;
    mbedtls_ecp_point peer;
    mbedtls_ecp_point_init(&peer);
    mbedtls_mpi secret;
    mbedtls_mpi_init(&secret);
    uint8_t shared[32] = {}, extracted[32] = {};
    bool ok = mbedtls_ecp_point_read_binary(&ephemeral_.MBEDTLS_PRIVATE(grp), &peer, hello, 65) == 0 &&
      mbedtls_ecp_check_pubkey(&ephemeral_.MBEDTLS_PRIVATE(grp), &peer) == 0 &&
      mbedtls_ecdh_compute_shared(&ephemeral_.MBEDTLS_PRIVATE(grp), &secret, &peer, &ephemeral_.MBEDTLS_PRIVATE(d), rng, nullptr) == 0 &&
      mbedtls_mpi_write_binary(&secret, shared, 32) == 0 && hmac(digest_, shared, sizeof(shared), extracted);
    static const uint8_t info[] = "ALTTECH-BLE-KEY-V2";
    uint8_t expand[sizeof(info) + 1]; memcpy(expand, info, sizeof(info)); expand[sizeof(info)] = 1;
    if (ok) ok = hmac(extracted, expand, sizeof(expand), session_);
    mbedtls_platform_zeroize(shared, sizeof(shared)); mbedtls_platform_zeroize(extracted, sizeof(extracted));
    mbedtls_mpi_free(&secret); mbedtls_ecp_point_free(&peer);
    mbedtls_ecp_keypair_free(&ephemeral_); mbedtls_ecp_keypair_init(&ephemeral_);
    started_ = millis(); pending_ = ok;
    if (!ok) reset();
    return ok;
  }
  bool reply(uint8_t output[161]) const {
    if (!pending_ || millis() - started_ >= 90000) return false;
    memcpy(output, serverHello_, 161); return true;
  }
  bool finish(const uint8_t* signature, size_t length, uint8_t ack[32]) {
    if (!pending_ || !signature || length < 8 || length > 72 || millis() - started_ >= 90000) return false;
    mbedtls_ecdsa_context phone;
    mbedtls_ecdsa_init(&phone);
    bool ok = mbedtls_ecp_group_load(&phone.MBEDTLS_PRIVATE(grp), MBEDTLS_ECP_DP_SECP256R1) == 0 &&
      mbedtls_ecp_point_read_binary(&phone.MBEDTLS_PRIVATE(grp), &phone.MBEDTLS_PRIVATE(Q), grant_.phoneKey, 65) == 0 &&
      mbedtls_ecp_check_pubkey(&phone.MBEDTLS_PRIVATE(grp), &phone.MBEDTLS_PRIVATE(Q)) == 0 &&
      mbedtls_ecdsa_read_signature(&phone, digest_, sizeof(digest_), signature, length) == 0;
    mbedtls_ecdsa_free(&phone);
    static const uint8_t label[] = "ALTTECH-BLE-READY-V2";
    uint8_t message[sizeof(label) + 32]; memcpy(message, label, sizeof(label)); memcpy(message + sizeof(label), digest_, 32);
    if (ok) ok = hmac(session_, message, sizeof(message), ack);
    complete_ = ok;
    if (!ok) reset();
    return ok;
  }
  bool key(uint8_t output[32]) const {
    if (!complete_ || !pending_ || millis() - started_ >= 90000) return false;
    memcpy(output, session_, 32); return true;
  }
  const AltAccess::Grant& grant() const { return grant_; }
  uint32_t estimatedTime() const { return phoneTime_ + (millis() - started_) / 1000; }

 private:
  mbedtls_ecp_keypair ephemeral_;
  AltAccess::Grant grant_;
  uint8_t session_[32] = {}, digest_[32] = {}, serverHello_[161] = {};
  uint32_t started_ = 0, phoneTime_ = 0;
  bool pending_ = false, complete_ = false;
  static int rng(void*, unsigned char* bytes, size_t length) {
    if (esp_bt_controller_get_status() != ESP_BT_CONTROLLER_STATUS_ENABLED) return MBEDTLS_ERR_ECP_RANDOM_FAILED;
    esp_fill_random(bytes, length); return 0;
  }
  static bool hmac(const uint8_t key[32], const uint8_t* message, size_t length, uint8_t out[32]) {
    return mbedtls_md_hmac(mbedtls_md_info_from_type(MBEDTLS_MD_SHA256), key, 32, message, length, out) == 0;
  }
};

#pragma once
#include <stdint.h>

namespace AltAccess {
// A lease may expire during transfer, but continuation is bounded and single-use.
class Transfer {
 public:
  static constexpr uint32_t MaxDurationMs = 30U * 60U * 1000U;
  void reset() { active_ = false; activated_ = false; startedAt_ = 0; }
  void begin(uint32_t now) { active_ = true; activated_ = false; startedAt_ = now; }
  bool ongoing(uint32_t now) const { return active_ && uint32_t(now - startedAt_) < MaxDurationMs; }
  bool activate(uint32_t now) {
    if (!ongoing(now) || activated_) return false;
    activated_ = true;
    return true;
  }
  const char* verifiedControllerFor(bool esc, bool begin, uint32_t now,
      const char* granted, const char* live) const {
    return esc && !begin && ongoing(now) ? granted : live;
  }
 private:
  uint32_t startedAt_ = 0;
  bool active_ = false, activated_ = false;
};
}

#pragma once

#include <Arduino.h>
#include <mbedtls/gcm.h>
#include <mbedtls/md.h>
#include <mbedtls/sha256.h>
#include "device_identity_runtime.h"

typedef bool (*AltFwWriteCallback)(const uint8_t* data, size_t length, void* context);

class AltFwDecoder {
public:
  static constexpr size_t Overhead = 241;
  AltFwDecoder() { reset(); }
  ~AltFwDecoder() { clearContexts(); }

  bool begin(size_t envelopeSize, size_t plainSize, const String& plainShaHex,
             const String& deviceId, AltFwWriteCallback callback, void* callbackContext) {
    clearContexts();
    reset();
    if(envelopeSize != plainSize + Overhead || !plainSize || plainSize > 16 * 1024 * 1024 ||
       !parseHex(plainShaHex, expectedPlainSha, sizeof(expectedPlainSha)) ||
       deviceId.length() != 12 || !callback) return fail("invalid_envelope_manifest");
    if (!identity.begin()) return fail("device_identity_unavailable");
    expectedEnvelopeSize = envelopeSize;
    expectedPlainSize = plainSize;
    writer = callback;
    writerContext = callbackContext;
    normalizedDeviceId = deviceId;
    normalizedDeviceId.toUpperCase();
    mbedtls_sha256_init(&plainSha);
    if(mbedtls_sha256_starts(&plainSha, 0) != 0) return fail("sha_init");
    plainShaActive = true;
    active = true;
    return true;
  }

  bool feed(const uint8_t* data, size_t length) {
    if(!active || !data || !length || envelopeReceived + length > expectedEnvelopeSize)
      return fail("invalid_envelope_length");
    size_t offset = 0;
    while(offset < length) {
      if(outerReceived < sizeof(outer)) {
        size_t take = min(length - offset, sizeof(outer) - outerReceived);
        memcpy(outer + outerReceived, data + offset, take);
        outerReceived += take; envelopeReceived += take; offset += take;
        continue;
      }
      if(headerReceived < sizeof(header)) {
        size_t take = min(length - offset, sizeof(header) - headerReceived);
        memcpy(header + headerReceived, data + offset, take);
        headerReceived += take;
        envelopeReceived += take;
        offset += take;
        if(headerReceived == sizeof(header) && !startContent()) return false;
        continue;
      }
      if(cipherReceived < expectedPlainSize) {
        size_t take = min(length - offset, expectedPlainSize - cipherReceived);
        if(!feedCipher(data + offset, take)) return false;
        cipherReceived += take;
        envelopeReceived += take;
        offset += take;
        continue;
      }
      size_t take = min(length - offset, sizeof(receivedTag) - tagReceived);
      memcpy(receivedTag + tagReceived, data + offset, take);
      tagReceived += take;
      envelopeReceived += take;
      offset += take;
    }
    return true;
  }

  bool finish() {
    if(!active || envelopeReceived != expectedEnvelopeSize || headerReceived != sizeof(header) ||
       cipherReceived != expectedPlainSize || tagReceived != sizeof(receivedTag))
      return fail("incomplete_envelope");
    if(cipherPendingLength && !writeDecrypted(cipherPending, cipherPendingLength)) return false;
    cipherPendingLength = 0;
    uint8_t trailing[15];
    size_t trailingLength = 0;
    uint8_t calculatedTag[16];
    if(mbedtls_gcm_finish(&contentGcm, trailing, sizeof(trailing), &trailingLength,
                          calculatedTag, sizeof(calculatedTag)) != 0)
      return fail("content_finish");
    if(trailingLength && (!writer(trailing, trailingLength, writerContext) ||
                          mbedtls_sha256_update(&plainSha, trailing, trailingLength) != 0))
      return fail("plaintext_write");
    plainProduced += trailingLength;
    uint8_t actualSha[32];
    if(mbedtls_sha256_finish(&plainSha, actualSha) != 0) return fail("sha_finish");
    plainShaActive = false;
    if(plainProduced != expectedPlainSize) return fail("plaintext_length");
    if(!secureEqual(actualSha, expectedPlainSha, sizeof(actualSha))) return fail("plaintext_sha");
    if(!secureEqual(calculatedTag, receivedTag, sizeof(calculatedTag))) return fail("envelope_tag");
    active = false;
    clearContexts();
    return true;
  }

  void abort() { active = false; clearContexts(); }
  size_t received() const { return envelopeReceived; }
  size_t envelopeSize() const { return expectedEnvelopeSize; }
  const char* error() const { return errorMessage; }

private:
  AltDeviceIdentity identity;
  uint8_t outer[105];
  size_t outerReceived;
  uint8_t header[120];
  uint8_t receivedTag[16];
  uint8_t cipherPending[16];
  uint8_t expectedPlainSha[32];
  mbedtls_gcm_context contentGcm;
  mbedtls_sha256_context plainSha;
  bool gcmActive;
  bool plainShaActive;
  bool active;
  size_t expectedEnvelopeSize;
  size_t expectedPlainSize;
  size_t envelopeReceived;
  size_t headerReceived;
  size_t cipherReceived;
  size_t tagReceived;
  size_t plainProduced;
  size_t cipherPendingLength;
  AltFwWriteCallback writer;
  void* writerContext;
  String normalizedDeviceId;
  const char* errorMessage;

  void reset() {
    memset(outer, 0, sizeof(outer)); outerReceived = 0;
    memset(header, 0, sizeof(header));
    memset(receivedTag, 0, sizeof(receivedTag));
    memset(cipherPending, 0, sizeof(cipherPending));
    memset(expectedPlainSha, 0, sizeof(expectedPlainSha));
    gcmActive = false;
    plainShaActive = false;
    active = false;
    expectedEnvelopeSize = expectedPlainSize = envelopeReceived = headerReceived = 0;
    cipherReceived = tagReceived = plainProduced = cipherPendingLength = 0;
    writer = nullptr;
    writerContext = nullptr;
    normalizedDeviceId = "";
    errorMessage = "";
  }

  void clearContexts() {
    if(gcmActive) { mbedtls_gcm_free(&contentGcm); gcmActive = false; }
    if(plainShaActive) { mbedtls_sha256_free(&plainSha); plainShaActive = false; }
  }

  bool fail(const char* message) {
    errorMessage = message;
    active = false;
    clearContexts();
    return false;
  }

  static bool parseHex(const String& value, uint8_t* output, size_t length) {
    if(value.length() != length * 2) return false;
    for(size_t i = 0; i < length; i++) {
      char pair[3] = { value[i * 2], value[i * 2 + 1], 0 };
      char* end = nullptr;
      long parsed = strtol(pair, &end, 16);
      if(!end || *end) return false;
      output[i] = (uint8_t)parsed;
    }
    return true;
  }

  static bool secureEqual(const uint8_t* left, const uint8_t* right, size_t length) {
    uint8_t difference = 0;
    for(size_t i = 0; i < length; i++) difference |= left[i] ^ right[i];
    return difference == 0;
  }

  static uint32_t readBe32(const uint8_t* data) {
    return ((uint32_t)data[0] << 24) | ((uint32_t)data[1] << 16) |
      ((uint32_t)data[2] << 8) | data[3];
  }

  bool deriveDeviceKey(uint8_t output[32]) {
    return outerReceived == sizeof(outer) && identity.firmwareWrapKey(outer, output);
  }

  bool startContent() {
    static const uint8_t magic[8] = { 'A','L','T','F','W','0','3',0 };
    if(!secureEqual(header, magic, sizeof(magic)) || readBe32(header + 8) != 3 ||
       readBe32(header + 12) != expectedPlainSize ||
       !secureEqual(header + 16, expectedPlainSha, sizeof(expectedPlainSha)))
      return fail("invalid_envelope_header");
    uint8_t deviceKey[32];
    uint8_t dataKey[32];
    if(!deriveDeviceKey(deviceKey)) return fail("device_key");
    mbedtls_gcm_context wrapGcm;
    mbedtls_gcm_init(&wrapGcm);
    int unwrapResult = mbedtls_gcm_setkey(&wrapGcm, MBEDTLS_CIPHER_ID_AES, deviceKey, 256);
    if(unwrapResult == 0) unwrapResult = mbedtls_gcm_auth_decrypt(
      &wrapGcm, 32, header + 60, 12, header, 72, header + 104, 16, header + 72, dataKey);
    mbedtls_gcm_free(&wrapGcm);
    memset(deviceKey, 0, sizeof(deviceKey));
    if(unwrapResult != 0) { memset(dataKey, 0, sizeof(dataKey)); return fail("key_unwrap"); }

    mbedtls_gcm_init(&contentGcm);
    gcmActive = true;
    int result = mbedtls_gcm_setkey(&contentGcm, MBEDTLS_CIPHER_ID_AES, dataKey, 256);
    memset(dataKey, 0, sizeof(dataKey));
    if(result == 0) result = mbedtls_gcm_starts(&contentGcm, MBEDTLS_GCM_DECRYPT, header + 48, 12);
    if(result == 0) result = mbedtls_gcm_update_ad(&contentGcm, header, 60);
    if(result != 0) return fail("content_init");
    return true;
  }

  bool writeDecrypted(const uint8_t* input, size_t length) {
    uint8_t output[143];
    size_t outputLength = 0;
    if(mbedtls_gcm_update(&contentGcm, input, length,
