// BLE callbacks only enqueue events. Crypto and flash run on this bounded worker.
class AltBleWorker {
 public:
  enum Kind : uint8_t { Connected, Disconnected, Write, Overflow };
  using Handler = void (*)(Kind, uint8_t*, size_t);
  bool begin(Handler handler) {
    handler_ = handler;
    queue_ = xQueueCreate(16, sizeof(Event));
    if (!queue_) return false;
    if (xTaskCreate(run, "alt-ble-work", 16384, this, 1, nullptr) == pdPASS) return true;
    vQueueDelete(queue_); queue_ = nullptr; return false;
  }
  void post(Kind kind, const uint8_t* data = nullptr, size_t size = 0) {
    if (!queue_ || size > 512 || (size && !data)) return;
    Event event{}; event.kind = kind; event.size = size;
    if (size) memcpy(event.data, data, size);
    if (xQueueSend(queue_, &event, 0) != pdTRUE) overflow_.store(true);
  }
 private:
  struct Event { Kind kind; size_t size; uint8_t data[512]; };
  QueueHandle_t queue_ = nullptr;
  Handler handler_ = nullptr;
  std::atomic<bool> overflow_{false};
  static void run(void* context) {
    auto& self = *static_cast<AltBleWorker*>(context);
    Event event;
    for (;;) {
      if (xQueueReceive(self.queue_, &event, portMAX_DELAY) != pdTRUE) continue;
      if (self.overflow_.exchange(false)) {
        xQueueReset(self.queue_);
        self.handler_(Overflow, nullptr, 0);
        continue;
      }
      self.handler_(event.kind, event.data, event.size);
    }
  }
};

