  if (length < 8 || length >= SerialSize) return false;
  for (size_t i = 0; i < length; ++i) {
    const unsigned char c = static_cast<unsigned char>(serial[i]);
    if (!(isalnum(c) || c == ':' || c == '_' || c == '-')) return false;
  }
