inline bool observe(Preferences& prefs, const char* serial, char binding[SerialSize]) {
  if (binding[0] || !valid(serial)) return false;
  if (prefs.putString(Key, serial) != strlen(serial)) return false;
  memset(binding, 0, SerialSize);
  memcpy(binding, serial, strlen(serial));
  return true;
}

