inline bool configure(Preferences& prefs, const char* requested, char binding[SerialSize]) {
  if (!requested || !requested[0] || !valid(requested)) return false;
  if (!strcmp(requested, binding)) return true;
  if (prefs.putString(Key, requested) != strlen(requested)) return false;
  memset(binding, 0, SerialSize);
  memcpy(binding, requested, strlen(requested));
  return true;
}

