      g.expires - g.issued > (g.purpose == 1 ? 86400U : 3600U)) return Result::Format;
  const uint16_t action = g.permissions & 31;
  if ((g.permissions & ~255U) || (g.role < 2 && (g.permissions & 96)) ||
      (g.purpose == 1 && action != 1) ||
      (g.purpose == 2 && action != 2 && action != 4 && action != 8 && action != 16)) return Result::Permission;
  if (bytes[112] != 4 || bytes[177] > 32) return Result::Format;
  for (size_t i = 0; i < 32; ++i) {
    const uint8_t c = bytes[178 + i];
    if (i >= bytes[177]) { if (c) return Result::Format; }
    else if (!((c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == ':' || c == '_' || c == '-')) return Result::Format;
