struct Context {
  const uint8_t* ownKeyHash = nullptr;
  // This must be a key whose possession the live BLE handshake has verified.
  const uint8_t* provenPhoneKey = nullptr;
  const char* liveController = nullptr;
  const uint8_t* imageHash = nullptr;
  uint32_t now = 0;
  uint16_t requestedAction = 0;
  bool protectedController = false;
  bool universalBuild = false;
};

// The caller must first verify the server signature and authenticate the phone.
inline Result check(const Grant& g, const Context& c) {
  if (!c.now) return Result::ClockRequired;
  if (c.now < g.issued || c.now >= g.expires) return Result::Expired;
  if (!c.ownKeyHash || !same(g.deviceHash, c.ownKeyHash, 32)) return Result::Identity;
  if (!c.provenPhoneKey || !same(g.phoneKey, c.provenPhoneKey, 65)) return Result::Phone;
  if (c.requestedAction != (g.permissions & 31)) return Result::Permission;
