void handleOtaChunk(const uint8_t* data, size_t length)
{
  if(!bleAuthorized || !otaActive || length < 18) return;
  uint16_t sequence = data[2] | ((uint16_t)data[3] << 8);
  uint8_t payloadLength = data[4];
  if(!payloadLength || payloadLength > 128 || length != (size_t)payloadLength + 17)
  {
    notifyChunk(sequence, false, "invalid_chunk");
    return;
  }
  if(sequence < otaExpectedSequence)
  {
    notifyChunk(sequence, true);
    return;
  }
  if(sequence != otaExpectedSequence || otaReceived + payloadLength > otaExpectedEnvelopeSize)
  {
    notifyChunk(sequence, false, "sequence");
    return;
  }

  uint8_t counterData[4];
  writeCounterBE((uint32_t)sequence + 1, counterData);
  uint8_t macMessage[135];
  memcpy(macMessage, "OTM", 3);
  memcpy(macMessage + 3, counterData, 4);
  memcpy(macMessage + 7, data + 5, payloadLength);
  uint8_t expectedMac[32];
  hmacSha256Key(sessionKey, sizeof(sessionKey), macMessage, payloadLength + 7, expectedMac);
  if(!secureEqual(expectedMac, data + 5 + payloadLength, 12))
  {
    notifyChunk(sequence, false, "mac");
    return;
  }

  uint8_t plain[128];
  for(size_t offset = 0, block = 0; offset < payloadLength; offset += 32, block++)
  {
    uint8_t blockData[4];
    writeCounterBE(block, blockData);
    uint8_t streamMessage[11];
    memcpy(streamMessage, "OTA", 3);
    memcpy(streamMessage + 3, counterData, 4);
    memcpy(streamMessage + 7, blockData, 4);
    uint8_t stream[32];
    hmacSha256Key(sessionKey, sizeof(sessionKey), streamMessage, sizeof(streamMessage), stream);
    for(size_t i = 0; i < 32 && offset + i < payloadLength; i++)
      plain[offset + i] = data[5 + offset + i] ^ stream[i];
  }

  if(!otaEnvelope.feed(plain, payloadLength))
  {
    abortOta(otaEnvelope.error());
    return;
  }
  otaReceived = otaEnvelope.received();
  otaExpectedSequence++;
  if(otaAckEvery <= 1 || otaExpectedSequence % otaAckEvery == 0 ||
     otaReceived == otaExpectedEnvelopeSize)
    notifyChunk(sequence, true);
}

void finishOta()
{
  if(!otaActive || otaReceived != otaExpectedEnvelopeSize)
  {
    abortOta("incomplete_image");
    return;
  }
  notifyOtaStatus("verifying");
  if(!otaEnvelope.finish())
  {
    abortOta(otaEnvelope.error());
    return;
  }
  if(!Update.end(true))
  {
    abortOta("image_rejected");
    return;
  }
  otaActive = false;
  otaRebootAt = millis() + 1200;
  notifyOtaStatus("rebooting");
}

