void setup()
{
  Serial.begin(115200);
  firmwareDeviceId();
  scooterUart.begin(UART_BAUD, SERIAL_8N1, UART_RX, UART_TX);
  BLEDevice::init(DEVICE_NAME);
  BLEDevice::setMTU(185);
  serverPtr = BLEDevice::createServer();
  serverPtr->setCallbacks(new ServerCallbacks());
  BLEService* service = serverPtr->createService(SERVICE_UUID);
  BLECharacteristic* tx = service->createCharacteristic(
    TX_UUID, BLECharacteristic::PROPERTY_WRITE | BLECharacteristic::PROPERTY_WRITE_NR);
  tx->setCallbacks(new TxCallbacks());
  rxChar = service->createCharacteristic(
    RX_UUID, BLECharacteristic::PROPERTY_NOTIFY | BLECharacteristic::PROPERTY_READ);
  rxChar->addDescriptor(new BLE2902());
  service->start();
  BLEAdvertising* advertising = BLEDevice::getAdvertising();
  advertising->addServiceUUID(SERVICE_UUID);
  advertising->start();
  Serial.println("USNSC BLE bootstrap 0.0.0 ready");
}

void loop()
{
  uint32_t now = millis();
  if(otaRebootAt && (int32_t)(now - otaRebootAt) >= 0) ESP.restart();
  if(now - lastHeartbeat >= HEARTBEAT_INTERVAL)
  {
    scooterUart.write(SCOOTER_HEARTBEAT, sizeof(SCOOTER_HEARTBEAT));
    lastHeartbeat = now;
  }
  delay(2);
}

